/*commonPopupMprq.newSourcingNegoBuyerList*/ SELECT A.BUYER, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE=A.BUYER AND STATUS <> 'D')) AS BUYER_NAME, COUNT(*) CNT FROM KEPRQDT A, KEPQTDT B, ( SELECT BUYER FROM BUYEROWN WHERE USER_ID = #{USER_ID})M WHERE A.BUYER = B.BUYER AND A.BUYER = M.BUYER AND A.QUOTATION_NO=B.QUOTATION_NO AND A.QUOTATION_SEQ=B.QUOTATION_SEQ AND A.REVISION=B.REVISION AND A.SO_CA_FLAG = 'SO' AND A.RECV_FLAG <> 'GD' AND A.ATOB_UNIT_PRICE = 0 AND A.BTOA_NEGO_PRICE <> 0 AND A.ATOB_SEND_FLAG = 'Y' AND B.BID_SUCCESS_FLAG ='Y' AND B.STATUS(+) <> 'O' AND (A.STATUS = 'C' OR A.STATUS = 'R')
AND A.BUYER IN ( SELECT A.BUYER FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{USER_ID} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{USER_ID} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT BUYER FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{USER_ID} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{USER_ID} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
GROUP BY A.BUYER

mapper.update:

	UPDATE KEPRQDT /*saveScmRemark*/
       SET SCM_REMARK     = #{st_return_remark}
     WHERE BUYER         = #{st_buyer}
       AND QUOTATION_NO  = #{st_quotation_no}
       AND QUOTATION_SEQ = #{st_quotation_seq}
       AND REVISION      = #{st_revision}
       AND STATUS       <> 'D'
